"""Minimal Fitbit Web API client that reuses the mcp-fitbit token store.

- Reads the access token from the shared .fitbit-token.json.
- If it's expired, refreshes it against the Fitbit OAuth endpoint using the
  client id/secret from the shared .env, then writes the rotated token back in
  the same JSON shape the MCP server expects (so both stay in sync).

Note on token rotation: Fitbit rotates the refresh_token on every refresh. If
the long-running MCP server refreshes at the same moment, one side can end up
with a stale refresh_token. In practice the windows don't overlap (this app is
used at bedtime; the MCP only during Claude sessions), but if the MCP ever
fails to refresh, just re-auth it once and both pick up the new token.
"""
import base64
import datetime as dt
import json
import os

import requests

import config


class FitbitAuthError(RuntimeError):
    pass


def _load_creds():
    """Read FITBIT_CLIENT_ID / SECRET from the shared MCP .env."""
    cid = cs = None
    try:
        with open(config.ENV_PATH) as f:
            for line in f:
                line = line.strip()
                if line.startswith("FITBIT_CLIENT_ID="):
                    cid = line.split("=", 1)[1].strip().strip('"')
                elif line.startswith("FITBIT_CLIENT_SECRET="):
                    cs = line.split("=", 1)[1].strip().strip('"')
    except FileNotFoundError:
        pass
    # Fall back to env vars if the .env didn't have them.
    cid = cid or os.environ.get("FITBIT_CLIENT_ID")
    cs = cs or os.environ.get("FITBIT_CLIENT_SECRET")
    if not cid or not cs:
        raise FitbitAuthError(
            "Fitbit client id/secret not found in MCP .env or environment."
        )
    return cid, cs


def _load_token():
    with open(config.TOKEN_PATH) as f:
        return json.load(f)


def _save_token(token):
    with open(config.TOKEN_PATH, "w") as f:
        json.dump(token, f, indent=2)


def _is_expired(token):
    exp = token.get("expires_at")
    if not exp:
        return True
    # Stored as e.g. "2026-06-03T08:10:36.886Z"
    exp = exp.replace("Z", "+00:00")
    try:
        expires_at = dt.datetime.fromisoformat(exp)
    except ValueError:
        return True
    now = dt.datetime.now(dt.timezone.utc)
    # Refresh a couple minutes early to avoid edge-of-expiry failures.
    return expires_at <= now + dt.timedelta(minutes=2)


def _refresh(token):
    cid, cs = _load_creds()
    basic = base64.b64encode(f"{cid}:{cs}".encode()).decode()
    resp = requests.post(
        "https://api.fitbit.com/oauth2/token",
        headers={
            "Authorization": f"Basic {basic}",
            "Content-Type": "application/x-www-form-urlencoded",
        },
        data={
            "grant_type": "refresh_token",
            "refresh_token": token["refresh_token"],
        },
        timeout=20,
    )
    if resp.status_code != 200:
        raise FitbitAuthError(
            f"Token refresh failed ({resp.status_code}): {resp.text[:300]}"
        )
    new = resp.json()
    expires_at = dt.datetime.now(dt.timezone.utc) + dt.timedelta(
        seconds=int(new.get("expires_in", 28800))
    )
    # Mirror the MCP's stored shape (it uses millisecond Z timestamps).
    new["expires_at"] = (
        expires_at.isoformat(timespec="milliseconds").replace("+00:00", "Z")
    )
    _save_token(new)
    return new


def get_access_token():
    token = _load_token()
    if _is_expired(token):
        token = _refresh(token)
    return token["access_token"]


def get_sleep_range(start_date, end_date):
    """Fetch sleep logs (with stages) for an inclusive date range.

    Dates are date objects or YYYY-MM-DD strings. Returns the raw `sleep` list
    from the Fitbit 1.2 sleep API (each entry includes levels.data stages).
    """
    if hasattr(start_date, "isoformat"):
        start_date = start_date.isoformat()
    if hasattr(end_date, "isoformat"):
        end_date = end_date.isoformat()
    token = get_access_token()
    url = (
        f"https://api.fitbit.com/1.2/user/-/sleep/date/"
        f"{start_date}/{end_date}.json"
    )
    resp = requests.get(
        url, headers={"Authorization": f"Bearer {token}"}, timeout=30
    )
    if resp.status_code == 401:
        # Token may have just expired; force one refresh and retry.
        _refresh(_load_token())
        token = get_access_token()
        resp = requests.get(
            url, headers={"Authorization": f"Bearer {token}"}, timeout=30
        )
    resp.raise_for_status()
    return resp.json().get("sleep", [])

"""Fitbit Sleep Cycle Alarm — Flask backend.

Computes a personalized sleep-cycle length from your Fitbit history, then tells
you the optimal wake time for N completed cycles so you can set your Charge 5's
native Smart Wake alarm to it.
"""
import datetime as dt

from flask import Flask, jsonify, render_template, request

import config
import cycle_analysis
import fitbit_client

app = Flask(__name__)
PORT = config.PORT

# Cache the profile for the process lifetime; it changes slowly (nightly).
_profile_cache = {"data": None}


def _compute_profile():
    end = dt.date.today()
    start = end - dt.timedelta(days=config.HISTORY_DAYS)
    logs = fitbit_client.get_sleep_range(start, end)
    return cycle_analysis.analyze_profile(logs)


@app.route("/")
def index():
    return render_template("index.html")


@app.route("/api/health")
def health():
    return jsonify({"ok": True})


@app.route("/api/profile")
def profile():
    refresh = request.args.get("refresh") == "1"
    if refresh or _profile_cache["data"] is None:
        try:
            _profile_cache["data"] = _compute_profile()
        except Exception as e:  # surface auth/network errors to the UI
            return jsonify({"error": str(e)}), 502
    return jsonify(_profile_cache["data"])


@app.route("/api/recommend")
def recommend():
    bedtime = request.args.get("bedtime")
    if not bedtime:
        bedtime = dt.datetime.now().replace(second=0, microsecond=0).isoformat()
    try:
        cycle_min = int(request.args.get("cycle_min", config.DEFAULT_CYCLE_MIN))
        onset = int(
            request.args.get("onset", config.DEFAULT_ONSET_LATENCY_MIN)
        )
    except ValueError:
        return jsonify({"error": "cycle_min and onset must be integers"}), 400
    try:
        result = cycle_analysis.recommend(bedtime, cycle_min, onset)
    except ValueError as e:
        return jsonify({"error": f"bad bedtime: {e}"}), 400
    return jsonify(result)


if __name__ == "__main__":
    app.run(port=PORT, debug=False)

"""Desktop shell — runs Flask in-process and renders it in a native macOS
WKWebView window via pywebview (no Chromium, low RAM). Mirrors the pattern used
by the other ~/Documents apps.
"""
import os
import sys
import threading
import time
import urllib.request

import webview

import app as backend

URL = f"http://127.0.0.1:{backend.PORT}/"

# The .app launches detached, so tee logs to a file for debugging.
try:
    _logf = open(
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "desktop.log"),
        "a",
        buffering=1,
    )
    sys.stdout = sys.stderr = _logf
except Exception:
    pass


def _server_up():
    try:
        urllib.request.urlopen(URL + "api/health", timeout=1)
        return True
    except Exception:
        return False


def _run_server():
    backend.app.run(port=backend.PORT, debug=False, use_reloader=False)


def main():
    if not _server_up():
        threading.Thread(target=_run_server, daemon=True).start()
        for _ in range(50):
            if _server_up():
                break
            time.sleep(0.1)
    webview.create_window(
        "Sleep Cycle Alarm", URL, width=540, height=860, min_size=(460, 640)
    )
    webview.start()


if __name__ == "__main__":
    main()

// Cache-first service worker — the app is fully static, so once cached it runs
// completely offline. Bump CACHE when you change any shell file.
const CACHE = 'sleep-cycle-v1';
const SHELL = [
  './',
  './index.html',
  './manifest.webmanifest',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/apple-touch-icon.png'
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  e.respondWith(
    caches.match(e.request).then(hit => hit || fetch(e.request).then(resp => {
      const copy = resp.clone();
      caches.open(CACHE).then(c => c.put(e.request, copy)).catch(()=>{});
      return resp;
    }).catch(() => caches.match('./index.html')))
  );
});
